        $userId = $request->input('user_id');

        if (!$userId) {
            return response()->json([
                'ok' => false,
                'message' => 'user_id es requerido'
            ], 400);
        }

        $updated = DB::connection('fuelcontrol')
            ->table('notificacion_usuarios')
            ->where('notificacion_id', $id)
            ->where('user_id', $userId)
            ->update([
                'leido' => 1,
                'updated_at' => now()
            ]);

