        // Solo intentamos en productos sin conversión y cuya unidad sea "Unidades"
        // (o variantes), ya que los líquidos en Odoo suelen estar como unidades sueltas.
        $sinConversion = $products->filter(
            fn($p) => !$conversiones->has($p->id)
