function odooStatus($m): array {
    if (!$m) return ['badge-gray',   '—',  'Sin match'];
    return match($m->estado) {
        'ok'       => ['badge-green',  '✔',  'Odoo OK ('       . $m->score . ')'],
        'probable' => ['badge-yellow', '⚠',  'Odoo probable (' . $m->score . ')'],
        default    => ['badge-red',    '✖',  'Odoo manual ('   . $m->score . ')'],
    };
}
